import { createHash } from "node:crypto";
import type { ZodiacSign } from "@/lib/contract/common";

/** Same number for every reader of a sign in a given week, 1 to 99. Computed, never generated by a model. */
export function luckyNumber(sign: ZodiacSign, weekStart: string): number {
  const digest = createHash("sha256").update(`lucky:${sign}:${weekStart}`).digest();
  return (digest.readUInt32BE(0) % 99) + 1;
}
